def admit_command_message_source(source, owner_sources):
    tree = ast.parse(source)
    if ast.dump(tree, include_attributes=False) != EXPECTED_MODULE_AST:
        raise ValueError('finite command-message module differs from its complete admitted AST')
    constants = {}
    for node in tree.body:
        if (isinstance(node, ast.Assign) and len(node.targets) == 1
                and isinstance(node.targets[0], ast.Name)
                and node.targets[0].id in ('VIEW_SPECS', 'CHILD_ADAPTERS', 'LOCAL_IMPORT_ADAPTERS', 'COMMAND_ENTRIES')):
            constants[node.targets[0].id] = ast.literal_eval(node.value)
    definitions = [node for node in tree.body if isinstance(node, ast.FunctionDef)
        and node.name in ('_dump', '_cooperative_tree', '_require_literal_command_routes')]
    if len(definitions) != 3:
        raise ValueError('complete finite command inverse definitions required')
    namespace = dict(ast=ast, copy=copy, **constants)
    exec(compile(ast.Module(body=definitions, type_ignores=[]),
        '<source-only command inverse admission>', 'exec'), namespace)
    highbank_nodes = {node.name: node for node in ast.parse(owner_sources['highbank']).body
        if isinstance(node, ast.FunctionDef)}
    namespace['_require_literal_command_routes'](highbank_nodes['_command_policy_child_fields'])
    functions, substitutions = 0, 0
    for group, expected_functions in EXPECTED_OWNER_ASTS.items():
        nodes = {node.name: node for node in ast.parse(owner_sources[group]).body
            if isinstance(node, ast.FunctionDef)}
        for name, expected in expected_functions.items():
            if name not in nodes or ast.dump(nodes[name], include_attributes=False) != expected:
                raise ValueError('whole original command dependency changed: ' + name)
            view, counts = namespace['_cooperative_tree'](group, nodes[name])
            compile(ast.fix_missing_locations(ast.Module(body=[view], type_ignores=[])),
                '<unexecuted cooperative command source>', 'exec', dont_inherit=True)
            functions += 1
            substitutions += sum(counts.values())
    return dict(complete_module_AST=True, complete_original_function_inverses=functions,
        finite_CALL_propagation_sites=substitutions, wait=0x30A90,
        native_lowerers_changed=False, business_executed=False, new_formal_bytes=0)
